import assert from 'node:assert/strict';
import {preview} from 'vite';
import {chromium} from 'playwright';

const root=new URL('../',import.meta.url).pathname;
const server=await preview({root,preview:{host:'127.0.0.1',port:0}});
const origin='http://127.0.0.1:'+server.httpServer.address().port;
const browser=await chromium.launch({headless:true});
const results=[];
try{
 for(const width of [375,1265]){
  const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'});
  const page=await context.newPage();
  await page.route('**/api/**',route=>route.fulfill({status:503,json:{error:'not_connected_in_test'}}));
  await page.goto(origin+'/');
  await page.locator('[data-testid="hero-grid"]').waitFor();
  if(width<821)await page.locator('[data-testid="chat-launcher"]').click();
  await page.locator('.public-orientation').waitFor();
  assert.equal(await page.locator('.public-orientation').getAttribute('data-orientation-mode'),'local-public-pages');
  assert.equal(await page.locator('.orientation-intro h3').first().innerText(),'Was planen Sie?');
  assert.equal(await page.locator('.orientation-starter').count(),3);
  assert.equal(await page.locator('.orientation-path').count(),0);
  assert.equal(await page.locator('.orientation-intro .state-label').count(),0);
  assert.match(await page.locator('.orientation-mode-note').innerText(),/ohne Live-KI/);
  await page.locator('.orientation-starter').first().click();
  const composer=page.locator('#orientation-message');
  assert.equal(await composer.evaluate(el=>document.activeElement===el),true);
  await composer.fill('Ich betreibe eine kleine Werkstatt und möchte eine Website mit Termin-Anfragen.');
  const activeButton=page.locator('.orientation-composer button.primary-button');
  assert.equal(await activeButton.isEnabled(),true);
  assert.equal(await activeButton.evaluate(el=>getComputedStyle(el).backgroundColor),'rgba(0, 0, 0, 0)');
  assert.equal(await activeButton.evaluate(el=>getComputedStyle(el).color),'rgb(168, 199, 106)');
  await page.locator('.orientation-composer button.primary-button').click();
  await page.locator('.orientation-message.role-assistant').waitFor();
  const brief=page.locator('#orientation-brief-text');
  await brief.waitFor();
  assert.match(await brief.inputValue(),/kleine Werkstatt/);
  const edited='Werkstatt-Webseite mit Termin-Anfragen und klarer Leistungsübersicht. Budget und Zeitraum besprechen wir persönlich.';
  await brief.fill(edited);
  await composer.fill('Außerdem brauche ich eine verständliche mobile Ansicht.');
  await page.locator('.orientation-composer button.primary-button').click();
  await page.locator('.orientation-message.role-assistant').last().waitFor();
  await page.waitForFunction(()=>document.querySelector('#orientation-brief-text')?.value.includes('Außerdem brauche ich'));
  const updated=await brief.inputValue();
  assert.ok(updated.startsWith(edited));
  await page.locator('.orientation-brief-actions a[href="/kontakt"]').click();
  await page.locator('[data-testid="contact-form"]').waitFor();
  assert.equal(await page.locator('[data-testid="contact-message"]').inputValue(),updated);
  assert.equal(await page.locator('[data-testid="contact-success"]').count(),0);
  assert.equal(await page.evaluate(()=>sessionStorage.getItem('nexify-oracle-brief-transfer-v1')),null);
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);
  results.push({width,brief_prefilled:true,auto_submitted:false,overflow:false});
  await context.close();
 }
 const context=await browser.newContext({viewport:{width:375,height:900}});
 await context.addInitScript(()=>{const original=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){if(key==='nexify-oracle-brief-transfer-v1')throw new Error('blocked');return original.call(this,key,value);};});
 const page=await context.newPage();await page.route('**/api/**',route=>route.fulfill({status:503,json:{error:'not_connected_in_test'}}));
 await page.goto(origin+'/');await page.locator('[data-testid="chat-launcher"]').click();await page.locator('.public-orientation').waitFor();
 await page.locator('#orientation-message').fill('Ich suche eine neue Website für meinen Betrieb.');
 await page.locator('.orientation-composer button.primary-button').click();await page.locator('#orientation-brief-text').waitFor();
 await page.locator('.orientation-brief-actions a[href="/kontakt"]').click();
 assert.equal(await page.locator('[data-testid="contact-form"]').count(),0);
 assert.match(await page.locator('.orientation-brief-notice').innerText(),/Kopieren Sie den Text/);
 results.push({blocked_storage:'kept_brief_and_route'});await context.close();
 const mobile=await browser.newContext({viewport:{width:375,height:900}});
 const sheet=await mobile.newPage();await sheet.route('**/api/**',route=>route.fulfill({status:503,json:{error:'not_connected_in_test'}}));
 await sheet.goto(origin+'/');await sheet.locator('[data-testid="chat-launcher"]').click();await sheet.locator('.public-orientation').waitFor();
 await sheet.locator('[data-testid="chat-panel-close-button"]').click();
 await sheet.waitForFunction(()=>document.querySelector('#aifly-panel')?.hidden===true);
 assert.equal(await sheet.evaluate(()=>document.activeElement?.getAttribute('data-testid')),'chat-launcher');
 results.push({mobile_close_focus:'returned_to_launcher'});await mobile.close();
 const isolated=await browser.newContext({viewport:{width:1265,height:900}});
 const scoped=await isolated.newPage();await scoped.route('**/api/**',route=>route.fulfill({status:503,json:{error:'not_connected_in_test'}}));
 await scoped.goto(origin+'/');
 await scoped.evaluate(()=>sessionStorage.setItem('nexify-oracle-brief-transfer-v1',JSON.stringify({source:'nexify-oracle',created_at:Date.now(),text:'Nur die NeXify-Anfrage darf diesen Entwurf verwenden.'})));
 await scoped.goto(origin+'/teileklar/termine');await scoped.locator('[data-testid="contact-form"]').waitFor();
 assert.equal(await scoped.locator('[data-testid="contact-message"]').inputValue(),'');
 assert.ok(await scoped.evaluate(()=>sessionStorage.getItem('nexify-oracle-brief-transfer-v1')));
 await scoped.goto(origin+'/kontakt');await scoped.locator('[data-testid="contact-form"]').waitFor();
 assert.match(await scoped.locator('[data-testid="contact-message"]').inputValue(),/Nur die NeXify-Anfrage/);
 await scoped.evaluate(()=>sessionStorage.setItem('nexify-oracle-brief-transfer-v1',JSON.stringify({source:'nexify-oracle',created_at:Date.now()-31*60*1000,text:'Veralteter Entwurf'})));
 await scoped.reload();await scoped.locator('[data-testid="contact-form"]').waitFor();
 assert.equal(await scoped.locator('[data-testid="contact-message"]').inputValue(),'');
 results.push({tenant_separation:'passed',expired_brief:'discarded'});await isolated.close();
 console.log(JSON.stringify({passed:true,results}));
}finally{await browser.close();await new Promise(done=>server.httpServer.close(done));}
